#!/usr/bin/env python3
"""Analyze workflow JSON output generated by fortran_to_workflow.py."""

import argparse
import json
import statistics
from collections import Counter, defaultdict
from pathlib import Path
from typing import Any


def load_workflow_json(file_path: Path) -> dict[str, Any]:
    """Load and validate basic structure of the workflow JSON file."""
    with file_path.open("r", encoding="utf-8") as f:
        data = json.load(f)

    if not isinstance(data, dict) or "nodes" not in data or "edges" not in data:
        raise ValueError("Invalid workflow JSON: expected top-level 'nodes' and 'edges' keys.")

    return data


def compute_statistics(data: dict[str, Any], top_n: int = 10) -> dict[str, Any]:
    """Compute structural, dependency, and graph metrics from workflow data."""
    nodes = data.get("nodes", [])
    edges = data.get("edges", [])

    node_by_id: dict[str, dict[str, Any]] = {n["id"]: n for n in nodes if "id" in n}
    node_type_counts = Counter(n.get("type", "unknown") for n in nodes)

    # Parent/child hierarchy analysis
    orphan_subroutines = [
        n for n in nodes if n.get("type") == "subroutine" and n.get("parentId") is None
    ]
    subroutines_per_module: Counter[str] = Counter()
    for n in nodes:
        if n.get("type") == "subroutine" and n.get("parentName"):
            subroutines_per_module[n["parentName"]] += 1

    # Edge classification & degree metrics
    edge_type_counts = Counter(e.get("type", "unknown") for e in edges)
    edge_label_counts = Counter(e.get("label", "unlabeled") for e in edges)

    in_degree_all: Counter[str] = Counter()
    out_degree_all: Counter[str] = Counter()
    in_degree_use: Counter[str] = Counter()
    out_degree_use: Counter[str] = Counter()
    call_in_degree: Counter[str] = Counter()
    only_import_counts: Counter[str] = Counter()
    cross_module_edges = 0
    internal_module_edges = 0
    dangling_edges = 0

    for e in edges:
        src = e.get("source")
        tgt = e.get("target")
        etype = e.get("type")
        label = e.get("label", "")

        if src not in node_by_id or tgt not in node_by_id:
            dangling_edges += 1
            continue

        out_degree_all[src] += 1
        in_degree_all[tgt] += 1

        if etype == "use":
            out_degree_use[src] += 1
            in_degree_use[tgt] += 1

            if label.startswith("CALL "):
                call_in_degree[tgt] += 1
            elif label.startswith("ONLY: "):
                symbol = label.removeprefix("ONLY: ").strip()
                only_import_counts[symbol] += 1

            src_node = node_by_id[src]
            tgt_node = node_by_id[tgt]
            src_mod = src_node["title"] if src_node.get("type") == "module" else src_node.get("parentName")
            tgt_mod = tgt_node["title"] if tgt_node.get("type") == "module" else tgt_node.get("parentName")

            if src_mod and tgt_mod:
                if src_mod == tgt_mod:
                    internal_module_edges += 1
                else:
                    cross_module_edges += 1

    # Isolated nodes (no incoming or outgoing edges)
    connected_ids = set(in_degree_all.keys()) | set(out_degree_all.keys())
    isolated_nodes = [n for n in nodes if n["id"] not in connected_ids]

    # Spatial layout bounds
    xs = [n["position"]["x"] for n in nodes if isinstance(n.get("position"), dict) and "x" in n["position"]]
    ys = [n["position"]["y"] for n in nodes if isinstance(n.get("position"), dict) and "y" in n["position"]]

    # Helper to format top node rankings
    def top_nodes(counter: Counter[str], limit: int) -> list[dict[str, Any]]:
        results = []
        for node_id, count in counter.most_common(limit):
            node = node_by_id.get(node_id, {})
            results.append({
                "id": node_id,
                "title": node.get("title", "<unknown>"),
                "type": node.get("type", "unknown"),
                "parent": node.get("parentName"),
                "count": count,
            })
        return results

    subs_counts = list(subroutines_per_module.values())
    module_size_stats = {
        "modules_with_subroutines": len(subs_counts),
        "empty_modules": node_type_counts.get("module", 0) - len(subs_counts),
        "min_subroutines": min(subs_counts) if subs_counts else 0,
        "max_subroutines": max(subs_counts) if subs_counts else 0,
        "mean_subroutines": round(statistics.mean(subs_counts), 2) if subs_counts else 0.0,
        "median_subroutines": round(statistics.median(subs_counts), 2) if subs_counts else 0.0,
    }

    return {
        "schema_version": data.get("version"),
        "overview": {
            "total_nodes": len(nodes),
            "node_types": dict(node_type_counts),
            "total_edges": len(edges),
            "edge_types": dict(edge_type_counts),
            "isolated_nodes": len(isolated_nodes),
            "dangling_edges": dangling_edges,
            "orphan_subroutines": len(orphan_subroutines),
        },
        "module_hierarchy": {
            **module_size_stats,
            "largest_modules": [
                {"module": mod, "subroutines": cnt}
                for mod, cnt in subroutines_per_module.most_common(top_n)
            ],
        },
        "dependencies": {
            "internal_module_use_edges": internal_module_edges,
            "cross_module_use_edges": cross_module_edges,
            "most_called_targets": top_nodes(call_in_degree, top_n),
            "most_depended_on_overall": top_nodes(in_degree_use, top_n),
            "highest_out_degree_nodes": top_nodes(out_degree_use, top_n),
            "most_imported_only_symbols": [
                {"symbol": sym, "count": cnt}
                for sym, cnt in only_import_counts.most_common(top_n)
            ],
        },
        "layout_bounds": {
            "x_min": min(xs) if xs else None,
            "x_max": max(xs) if xs else None,
            "y_min": min(ys) if ys else None,
            "y_max": max(ys) if ys else None,
        },
    }


def print_report(stats: dict[str, Any], file_path: Path) -> None:
    """Render a clean human-readable summary to stdout."""
    ov = stats["overview"]
    mh = stats["module_hierarchy"]
    dep = stats["dependencies"]
    lb = stats["layout_bounds"]

    print("=" * 68)
    print(f"WORKFLOW GRAPH STATISTICS: {file_path.name} (Schema v{stats['schema_version']})")
    print("=" * 68)

    print("\n[1] GRAPH OVERVIEW")
    print(f"  Total Nodes          : {ov['total_nodes']:,}")
    for ntype, cnt in sorted(ov["node_types"].items()):
        pct = (cnt / ov["total_nodes"] * 100) if ov["total_nodes"] else 0
        print(f"    - {ntype:<16} : {cnt:,} ({pct:.1f}%)")
    print(f"  Total Edges          : {ov['total_edges']:,}")
    for etype, cnt in sorted(ov["edge_types"].items()):
        pct = (cnt / ov["total_edges"] * 100) if ov["total_edges"] else 0
        print(f"    - {etype:<16} : {cnt:,} ({pct:.1f}%)")
    print(f"  Isolated Nodes       : {ov['isolated_nodes']:,}")
    print(f"  Orphan Subroutines   : {ov['orphan_subroutines']:,} (parentId is null)")
    print(f"  Dangling Edges       : {ov['dangling_edges']:,}")

    print("\n[2] MODULE HIERARCHY")
    print(f"  Modules w/ Routines  : {mh['modules_with_subroutines']} (Empty: {mh['empty_modules']})")
    print(
        f"  Routines / Module    : min={mh['min_subroutines']}, "
        f"median={mh['median_subroutines']}, mean={mh['mean_subroutines']}, "
        f"max={mh['max_subroutines']}"
    )
    print("  Largest Modules:")
    for item in mh["largest_modules"]:
        print(f"    - {item['module']:<32} : {item['subroutines']:,} subroutines")

    print("\n[3] DEPENDENCY & CALL METRICS")
    print(f"  Internal Module Uses : {dep['internal_module_use_edges']:,}")
    print(f"  Cross-Module Uses    : {dep['cross_module_use_edges']:,}")

    print("  Most Called Procedures (CALL edges):")
    for item in dep["most_called_targets"]:
        parent = f" [{item['parent']}]" if item["parent"] else ""
        print(f"    - {item['title']}{parent} ({item['type']}) : {item['count']:,} calls")

    print("  Most Depended-On Nodes (All 'use' in-degree):")
    for item in dep["most_depended_on_overall"]:
        parent = f" [{item['parent']}]" if item["parent"] else ""
        print(f"    - {item['title']}{parent} ({item['type']}) : {item['count']:,} incoming")

    print("  Highest Out-Degree Nodes (Most outgoing 'use' edges):")
    for item in dep["highest_out_degree_nodes"]:
        parent = f" [{item['parent']}]" if item["parent"] else ""
        print(f"    - {item['title']}{parent} ({item['type']}) : {item['count']:,} outgoing")

    print("  Most Frequently Imported Symbols (USE ..., ONLY:):")
    for item in dep["most_imported_only_symbols"]:
        print(f"    - {item['symbol']:<32} : {item['count']:,} imports")

    print("\n[4] CANVAS LAYOUT BOUNDS")
    print(f"  X Range              : {lb['x_min']} .. {lb['x_max']}")
    print(f"  Y Range              : {lb['y_min']} .. {lb['y_max']}")
    print("=" * 68)


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Compute and display statistics from a fortran_to_workflow.py JSON file."
    )
    parser.add_argument(
        "json_file",
        nargs="?",
        default="stdlibOUT.json",
        type=Path,
        help="Path to the workflow JSON file (default: stdlibOUT.json)",
    )
    parser.add_argument(
        "-n",
        "--top",
        type=int,
        default=10,
        help="Number of top items to display in rankings (default: 10)",
    )
    parser.add_argument(
        "--json-out",
        type=Path,
        default=None,
        help="Optional path to export computed statistics as JSON",
    )
    args = parser.parse_args()

    if not args.json_file.exists():
        raise FileNotFoundError(f"Input file not found: {args.json_file}")

    data = load_workflow_json(args.json_file)
    stats = compute_statistics(data, top_n=args.top)
    print_report(stats, args.json_file)

    if args.json_out:
        with args.json_out.open("w", encoding="utf-8") as f:
            json.dump(stats, f, indent=2)
        print(f"\nSaved JSON summary to: {args.json_out}")


if __name__ == "__main__":
    main()
